// readThroughWorkspaceSetting implements the cache read-through path for WorkspaceSetting:
// probe cache → hit returns decoded entity, miss runs the DB query under
// singleflight dedup and populates cache. Every backend call is breaker-gated;
// errors are routed through cache.RouteError and fall through to the DB so
// a cache outage never breaks the caller.
// Tenanted: tenant comes from q.Tenant — resolved once at the entity-method
// boundary and reused here without re-invoking TenantResolver.
func (c *Cache) readThroughWorkspaceSetting(ctx context.Context, tenant uuid.UUID, pk WorkspaceSettingPK, q *hook.QueryContext, next hook.QueryHandler) (any, error) {
	key := c.keyForWorkspaceSetting(tenant, pk)
	schema := "public"

	if c.breaker == nil || c.breaker.Allow() {
		getStart := time.Now()
		entity, hit, err := cache.GetAs[*WorkspaceSetting](ctx, c.backend, c.serializer, key)
		if c.metrics != nil {
			c.metrics.GetLatency(schema, TableWorkspaceSettings, time.Since(getStart))
		}
		if err != nil {
			cache.RouteError(ctx, c.metrics, c.onError, c.breaker, "get", schema, TableWorkspaceSettings, err)
		} else if hit {
			if c.metrics != nil {
				c.metrics.Hit(schema, TableWorkspaceSettings)
			}
			if c.breaker != nil {
				c.breaker.RecordSuccess()
			}
			return entity, nil
		} else {
			if c.metrics != nil {
				c.metrics.Miss(schema, TableWorkspaceSettings)
			}
			// A clean miss is a successful backend round-trip — it resets
			// the consecutive-failure counter and closes a HalfOpen probe.
			if c.breaker != nil {
				c.breaker.RecordSuccess()
			}
		}
	} else if c.metrics != nil {
		c.metrics.Miss(schema, TableWorkspaceSettings)
	}

	// Partial fetches must not write back to cache (invariant:
	// only full entities). On miss, run the DB through `next` with the
	// caller's partial FieldOptions, kick off fire-and-forget hydration to
	// refill the cache with the full entity, and return the
	// partial result directly. The partial + hydration-disabled case is
	// filtered out earlier in QueryHook.
	if extractFieldOptions(q.CallOptions) != nil {
		result, err := next(ctx, q)
		if err != nil {
			return nil, err
		}
		c.hydrateWorkspaceSetting(tenant, pk, next)
		return result, nil
	}

	ch := c.sf.DoChan(key, func() (any, error) {
		// In-flight cache re-check: a sibling flight may have populated the
		// cache between this caller's outer Get-miss and entering the flight.
		// Without this, late stragglers that arrive after the sibling flight
		// completed would register a new flight and run a duplicate DB query.
		// The outer probe already recorded the Miss / breaker success; this
		// inner re-check is dedup machinery, not an observable cache event, so
		// it emits no metrics.
		if c.breaker == nil || c.breaker.Allow() {
			if entity, hit, err := cache.GetAs[*WorkspaceSetting](ctx, c.backend, c.serializer, key); err == nil && hit {
				return entity, nil
			}
		}
		result, fetchErr := next(ctx, q)
		if fetchErr != nil {
			return nil, fetchErr
		}
		entity, ok := result.(*WorkspaceSetting)
		if !ok || entity == nil {
			return result, nil
		}
		if c.breaker != nil && !c.breaker.Allow() {
			return result, nil
		}
		setStart := time.Now()
		setErr := cache.SetAs(ctx, c.backend, c.serializer, key, entity, c.ttlForWorkspaceSetting())
		if c.metrics != nil {
			c.metrics.SetLatency(schema, TableWorkspaceSettings, time.Since(setStart))
		}
		if setErr != nil {
			cache.RouteError(ctx, c.metrics, c.onError, c.breaker, "set", schema, TableWorkspaceSettings, setErr)
			return result, nil
		}
		if c.breaker != nil {
			c.breaker.RecordSuccess()
		}
		if c.metrics != nil {
			c.metrics.Set(schema, TableWorkspaceSettings)
		}
		return result, nil
	})

	select {
	case res := <-ch:
		return res.Val, res.Err
	case <-ctx.Done():
		return nil, ctx.Err()
	}
}

